func getTargetForRedirect(target string, domain string) string {
    u, err := url.Parse(target)
    if err != nil {
        return "https://" + domain
    }

    // Clean the path to prevent directory traversal attacks
    u.Path = url.CleanPath(u.Path)

    // Remove any query parameters and fragments for security
    u.RawQuery = ""
    u.Fragment = ""

    targetHost := u.Hostname()
    if targetHost == "" {
        return "https://" + domain
    }

    // Split hostname and domain into parts
    targetParts := strings.Split(targetHost, ".")
    domainParts := strings.Split(domain, ".")

    // Check if target has enough parts to match the domain
    if len(targetParts) < len(domainParts) {
        return "https://" + domain
    }

    // Compare each part from the end
    var match bool = true
    for i := range domainParts {
        targetPart := targetParts[len(targetParts)-len(domainParts)+i]
        domainPart := domainParts[i]
        if targetPart != domainPart {
            match = false
            break
        }
    }

    if !match {
        return "https://" + domain
    }

    // Reconstruct the URL with https scheme and cleaned path
    u.Scheme = "https"
    result := u.String()

    return result
