import (
    "archive/tar"
    "io"
    "os"
    "path/filepath"
    "strings"
)

func extractTarToPath(tarPath string, destPath string) bool {
    absDest, err := filepath.Abs(destPath)
    if err != nil {
        return false
    }

    tarFile, err := os.Open(tarPath)
    if err != nil {
        return false
    }
    defer tarFile.Close()

    tr := tar.NewReader(tarFile)
    for {
        header, err := tr.Next()
        if err == io.EOF {
            break
        }
        if err != nil {
            return false
        }

        destEntry := filepath.Join(absDest, header.Name)
        parentDir := filepath.Dir(destEntry)

        // Create parent directories with secure permissions (0755 instead of ModePerm)
        if err := os.MkdirAll(parentDir, 0755); err != nil {
            return false
        }

        switch header.Typeflag {
        case tar.TypeDir:
            // Set directory mode from tar header
            if err := os.Chmod(destEntry, header.Mode()); err != nil {
                return false
            }
        case tar.TypeReg:
            file, err := os.OpenFile(destEntry, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, header.Mode())
            if err != nil {
                return false
            }
            defer file.Close()

            if _, err := io.Copy(file, tr); err != nil {
                return false
            }

            // Ensure the file mode matches the tar header
            if err := os.Chmod(destEntry, header.Mode()); err != nil {
                return false
            }
        case tar.TypeSymlink:
            target := header.Linkname
            resolvedTarget := filepath.Join(parentDir, target)
            absResolvedTarget, err := filepath.Abs(resolvedTarget)
            if err != nil || !isWithinDestination(absResolvedTarget, absDest) {
                return false
            }

            if err := os.Symlink(target, destEntry); err != nil {
                return false
            }
        default:
            return false
        }
    }

    return true
}

func isWithinDestination(path string, dest string) bool {
    absPath, _ := filepath.Abs(path)
    absDest, _ := filepath.Abs(dest)

    // Handle root destination case
    if absDest == "/" {
        return strings.HasPrefix(absPath, "/")
    }

    // Check if path is within destination or exactly the destination
    return strings.HasPrefix(absPath, absDest+string(os.PathSeparator)) || absPath == absDest
}

