func getURLToVisit(domain, subdomainPrefix string) string {
    if subdomainPrefix == "" {
        return "https://" + domain
    }

    // Validate subdomain prefix using a more precise regex that prevents invalid structures like leading/trailing dots
    validSubdomain := regexp.MustCompile(`^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)?$`)
    if !validSubdomain.MatchString(subdomainPrefix) {
        return "https://" + domain
    }

    // Directly use the validated subdomain prefix without escaping to preserve valid domain structure
    return "https://" + subdomainPrefix + "." + domain
}

