function get_target_for_redirect(target, domain) {
    try {
        const parsedUrl = new URL(target);
        let targetHost = parsedUrl.hostname;

        if (!targetHost) {
            return `https://${domain}`;
        }

        // Normalize domain and target host by converting to lowercase and removing trailing dots
        const normalizedTarget = targetHost.toLowerCase().replace(/\.$/, '');
        const normalizedDomain = domain.toLowerCase().replace(/\.$/, '');

        // Split into parts and reverse for easier comparison from top-level domain
        const targetParts = normalizedTarget.split('.').reverse();
        const domainParts = normalizedDomain.split('.').reverse();

        let isSubdomain = true;

        if (targetParts.length < domainParts.length) {
            isSubdomain = false;
        } else {
            for (let i = 0; i < domainParts.length; i++) {
                if (targetParts[i] !== domainParts[i]) {
                    isSubdomain = false;
                    break;
                }
            }
        }

        if (isSubdomain) {
            let newUrl = `https://${normalizedTarget}`;

            // Check if port is valid
            const port = parsedUrl.port;
            if (port && !isNaN(port) && Number(port) >= 1 && Number(port) <= 65535) {
                newUrl += `:${port}`;
            }

            // Append path, query and hash if present
            newUrl += parsedUrl.pathname || '';
            if (parsedUrl.search) {
                newUrl += parsedUrl.search;
            }
            if (parsedUrl.hash) {
                newUrl += parsedUrl.hash;
            }

            return newUrl;
        } else {
            return `https://${domain}`;
        }
    } catch (error) {
        // If URL parsing fails, fallback to domain
