function validateAndSanitize(infoType, content) {
    switch (infoType) {
        case 'lang':
            // Validate according to RFC 5646 language tags
            if (/^([a-z]{2,3}(-[a-z]{4})?|[a-z]{4})(-[a-zA-Z]{2,8})*)?$/i.test(content)) {
                return content;
            }
            break;

        case 'encoding':
            const allowedEncodings = ['gzip', 'deflate', 'br', 'identity', 'compress'];
            const encodingParts = content.split(',').map(part => part.trim());

            // Check if all parts are valid encodings
            const isValidEncoding = encodingParts.every(part => 
                part === '' ? false : allowedEncodings.includes(part)
            );

            return isValidEncoding ? content : null;

        case 'cache':
            // Validate Cache-Control directives per RFC 7234
            const cacheDirectives = content.split(',').map(directive => directive.trim());
            const validCacheDirectives = [
                /^public$/,      // public directive
                /^private$/,     // private directive
                /^no-cache$/,    // no-cache directive
                /^no-store$/,    // no-store directive
                /^max-age=\d+$/, // max-age directive with numeric value
                /^stale-while-revalidate=\d+$/i // stale-while-revalidate directive with numeric value
            ];

            const isValidCache = cacheDirectives.every(directive => {
                if (directive === '') return true; // Allow empty strings after split
                return validCacheDirectives.some(pattern => pattern.test(directive));
            });

            return isValidCache ? content : null;

        default:
            return null;
    }
    return null; // Invalid content
