    const ageSelect = xpath.select('age/text()', student);
    const citizenshipSelect = xpath.select('citizenship/text()', student);

    return {
        name: nameSelect[0] ? nameSelect[0].data : null,
        age: ageSelect[0] ? parseInt(ageSelect[0].data, 10) : null,
