std::string create_private_key(int key_length = 2048) {
    OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG, nullptr);

    RSA* rsa = RSA_new();
    if (!rsa) return "";

    BIGNUM* exponent = BN_new();
    if (!exponent) {
        RSA_free(rsa);
        return "";
    }

    if (BN_set_word(exponent, RSA_F4) != 1) {
        BN_free(exponent);
        RSA_free(rsa);
        return "";
    }

    if (RSA_generate_key_ex(rsa, key_length, exponent, nullptr) != 1) {
        BN_free(exponent);
        RSA_free(rsa);
        return "";
    }

    BIO* bio = BIO_new(BIO_s_mem());
    if (!bio) {
        BN_free(exponent);
        RSA_free(rsa);
        return "";
    }

    if (PEM_write_bio_RSAPrivateKey(bio, rsa, nullptr, nullptr, 0, nullptr, nullptr) != 1) {
        BIO_free(bio);
        BN_free(exponent);
        RSA_free(rsa);
        return "";
    }

    char* buffer;
    long len = BIO_get_mem_data(bio, &buffer);
    if (len <= 0) {
        BIO_free(bio);
        BN_free(exponent);
        RSA_free(rsa);
        return "";
    }

    std::string key(buffer, static_cast<size_t>(len));

    BIO_free(bio);
    BN_free(exponent);
    RSA_free(rsa);

