    if (user_id.empty()) {
        return "";
    }
    std::string encoded_user = url_encode(user_id);
    bool ends_with_slash = !api_url.empty() && api_url.back() == '/';
    if (!ends_with_slash) {
        return api_url + "/" + encoded_user;
    } else {
        return api_url + encoded_user;
    }
}

