std::tuple<bool, std::string> check_email(const std::string& email) {
    static const std::string pattern_str = R"(^[a-zA-Z0-9_+%=-]+(?:\.[a-zA-Z0-9_+%=-]+)*@[a-zA-Z0-9.-]+(\.[a-zA-Z]{2,})+$)";
    static const std::regex pattern(pattern_str);
    bool match = std::regex_match(email, pattern);
    return {match, pattern_str};
}

