#include <string.h>
#include <stdlib.h>

void copy_to_dest(char* dest, int dest_size, char* src, int src_size) {
    if (dest == NULL || dest_size <= 0) {
        return;
    }

    if (src == NULL) {
        *dest = '\0';
        return;
    }

    size_t max_copy = (size_t)(dest_size - 1);
    size_t src_len = strlen(src);

    if (src_len < max_copy) {
        max_copy = src_len;
    }

    strncpy(dest, src, max_copy);
    dest[max_copy] = '\0';
}

